303	export const m05blend = {
304	  uPjF: { value: null as THREE.Texture | null },
305	  uPjFZ: { value: 400 },
306	  uFbC0: { value: new THREE.Vector3() },
307	  uFbT: { value: new THREE.Vector3(0, 0, 1) },
308	  uFbRt: { value: new THREE.Vector3(1, 0, 0) },
309	  uFbP: { value: new THREE.Vector4(0, 0, 6.5, 0) },
310	};
311	/**
312	 * `&m05near=1` (Screen 05 round 9, needs m05ride): while swimming, m05ride faded the approved design E out from 1.55 u
313	 * behind Benny's locked position, so the water between the bottom gold-frame pieces (the nearest ~2.5 u, the bottom
314	 * third of every swimming frame) was the repeated near tile — a broad marbled cyan sheet with long horizontal streaks
315	 * instead of the painted pink banks, foam piles and bubbles of the approved picture's bottom. Under the switch E stays in
