348	/** m05blend: the ribbon's own clock uniform (the far river's first rows follow the ribbon's vertex wave at the seam) */
349	export const m05blendTime: { u: THREE.IUniform | null } = { u: null };
350	/** `?proj05=1`: texture loads of other proj05 parts (far block, bank strip) that the game waits for before `ready` */
351	export const proj05Pending: Promise<unknown>[] = [];
352	
353	/**
354	 * W11 geometry (`?farw05=1`, else the full width): the VISIBLE water channel of the 05 river at arc length s, in the
355	 * ribbon frame — centre `c` (units along `right`) and half width `hw`. Between the channel and the bank lies a foam
356	 * shelf (drawn by the ribbon shader on the same surface; Benny can still ride over it — widthAt() and the steering
357	 * range are unchanged). Approved image, banks traced through the locked 05 eye: a left shelf ≈1.3 u wide at
358	 * y 640–720 (s ≈ 145–155) and a right shelf that grows to ≈3.9 u at the seam (y 560–590, the big foam bank at
359	 * x 546–592) and continues into the far block; it hands back to the full width behind the seam (s 183–191, hidden
360	 * by the far block at the checkpoint, the ride into 06 is the normal river).
361	 */
362	export function channel05(course: Course, s: number): { c: number; hw: number } {
363	  const hw = course.widthAt(s) / 2;
364	  if (!FARW05) return { c: 0, hw };
365	  const st = course.stage('05');
366	  if (s <= st.s0 || s >= st.s1 + 4) return { c: 0, hw };
367	  const o = s - st.s0;                              // 05-relative arc length (the checkpoint is at o ≈ 17.75)
368	  const shL = 1.35 * smooth(25, 32, o) * (1 - smooth(39.5, 47, o));
369	  const shR = 3.7 * smooth(52, 65, o) * (1 - smooth(68.5, 76.5, o));
370	  const k = Math.min(1, (hw - 2.4) / Math.max(1e-3, (shL + shR) / 2));   // never narrower than 2.4 u half width
371	  const a = shL * Math.max(0, k), b = shR * Math.max(0, k);
372	  return { c: (a - b) / 2, hw: hw - (a + b) / 2 };
373	}
374	
375	export function ampAt(course: Course, s: number): number {
