      if (Number.isFinite(pid) && !alive(pid)) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* */ } }
    }
  }
  await new Promise((r) => setTimeout(r, 1500));
}
const { createServer } = await import('vite');
